from pathlib import Path
r=Path('apps/storefront')
(r/'components/store.tsx').write_text('''"use client";
import React,{createContext,useContext,useEffect,useRef,useState} from 'react';
import Link from 'next/link';
import Image from 'next/image';
import {useRouter} from 'next/navigation';
import {Leaf,Search,ShoppingBag,UserRound,Heart,Menu,X,ArrowRight,Truck,ShieldCheck,Headphones,MessageCircle,Plus,Minus,Trash2,Check,Star} from 'lucide-react';
import {Catalog,Product,price,money,slugify,storeRequest} from '@/lib/store';
type Line={id:string;quantity:number};
const Context=createContext<any>(null);
export const useStore=()=>useContext(Context);
export function StoreProvider({data,children}:{data:Catalog;children:React.ReactNode}){
 const [cart,setCart]=useState<Line[]>([]),[wishlist,setWishlist]=useState<string[]>([]),[account,setAccount]=useState<any>(null),[ready,setReady]=useState(false),[toast,setToast]=useState('');const timer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const notify=(message:string)=>{if(timer.current)clearTimeout(timer.current);setToast(message);timer.current=setTimeout(()=>setToast(''),4500);};
 const reloadAccount=async()=>{try{const result=await storeRequest('account');setAccount(result.customer);setWishlist(result.customer.wishlist??[]);return result;}catch{setAccount(null);return null;}};
 useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('olive-store-cart')||'[]');setCart(Array.isArray(saved)?saved.filter(line=>data.products.some(p=>p.id===line.id)&&Number.isInteger(line.quantity)&&line.quantity>0).map(line=>({...line,quantity:Math.min(line.quantity,100)})):[]);const favorites=JSON.parse(localStorage.getItem('olive-store-wishlist')||'[]');setWishlist(Array.isArray(favorites)?favorites:[]);}catch{}setReady(true);void reloadAccount();return()=>{if(timer.current)clearTimeout(timer.current);};},[]);
 useEffect(()=>{if(ready)localStorage.setItem('olive-store-cart',JSON.stringify(cart));},[cart,ready]);
 useEffect(()=>{if(ready)localStorage.setItem('olive-store-wishlist',JSON.stringify(wishlist));},[wishlist,ready]);
 const setQuantity=(id:string,quantity:number)=>{const product=data.products.find(p=>p.id===id);const max=product?Math.max(0,product.stock-(product.reserved||0)):0;setCart(lines=>quantity<=0?lines.filter(line=>line.id!==id):lines.map(line=>line.id===id?{id,quantity:Math.min(quantity,max)}:line));};
 const add=(product:Product,quantity=1)=>{const available=product.stock-(product.reserved||0);const existing=cart.find(line=>line.id===product.id)?.quantity||0;if(product.type!=='Simple'||available<=0){notify('This product is currently unavailable.');return;}if(existing+quantity>available){notify('There are not enough units available.');return;}setCart(lines=>existing?lines.map(line=>line.id===product.id?{...line,quantity:line.quantity+quantity}:line):[...lines,{id:product.id,quantity}]);notify('Added to your bag.');};
 const favorite=async(id:string)=>{const next=wishlist.includes(id)?wishlist.filter(value=>value!==id):[...wishlist,id];setWishlist(next);if(account){try{await storeRequest('profile','PATCH',{name:account.name,phone:account.phone,wishlist:next});}catch(error:any){notify(error.message);}}};
 return <Context.Provider value={{data,cart,setCart,setQuantity,add,wishlist,favorite,account,reloadAccount,notify}}>{children}{toast&&<div className="store-toast" role="status"><Check size={18}/>{toast}<button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={17}/></button></div>}</Context.Provider>;
}
export function Header(){const {data,cart,wishlist}=useStore();const [search,setSearch]=useState(''),[open,setOpen]=useState(false);const router=useRouter();const suggestions=search.trim()?data.products.filter((p:Product)=>p.name.toLowerCase().includes(search.toLowerCase())||p.sku.toLowerCase().includes(search.toLowerCase())).slice(0,5):[];
 return <><div className="announcement"><div className="container"><span>Thoughtfully chosen. Delivered to your door.</span><span><Truck size={13}/>Delivery across selected Kenyan counties</span></div></div><header className="store-header"><div className="container header-main"><Link href="/" className="store-logo" aria-label="Olive home"><span><Leaf size={24}/></span>olive<span className="logo-caption">HOME & LIVING</span></Link><form className="store-search" onSubmit={event=>{event.preventDefault();router.push('/products?q='+encodeURIComponent(search));setSearch('');}}><Search size={19}/><input aria-label="Search products" placeholder="What can we help you find?" value={search} onChange={event=>setSearch(event.target.value)} onKeyDown={event=>{if(event.key==='Escape')setSearch('');}}/><button type="submit" aria-label="Submit search"><ArrowRight size={18}/></button>{search.trim()&&<div className="search-suggestions">{suggestions.length?suggestions.map((p:Product)=><Link href={'/products/'+p.slug} key={p.id} onClick={()=>setSearch('')}><span>{p.name}</span><strong>{money(price(p))}</strong></Link>):<p>No products found. Try another search.</p>}</div>}</form><div className="header-tools"><Link href="/account" aria-label="My account"><UserRound size={22}/><small>Account</small></Link><Link href="/account?tab=wishlist" aria-label="Wishlist"><Heart size={22}/>{wishlist.length>0&&<b>{wishlist.length}</b>}</Link><Link href="/cart" aria-label="Shopping bag"><ShoppingBag size={22}/>{cart.length>0&&<b>{cart.reduce((sum:number,line:Line)=>sum+line.quantity,0)}</b>}</Link><button className="mobile-menu" aria-label="Toggle navigation" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></div></div><nav className={'container store-nav '+(open?'is-open':'')}><Link href="/products" onClick={()=>setOpen(false)}><Menu size={17}/>Shop all products</Link>{data.categories.filter((c:any)=>c.parent_id).slice(0,5).map((c:any)=><Link key={c.id} href={'/categories/'+c.slug} onClick={()=>setOpen(false)}>{c.name}</Link>)}<Link href="/products?sale=1" className="nav-offer" onClick={()=>setOpen(false)}>Special offers <ArrowRight size={14}/></Link></nav></header></>;
}
export function ProductImage({product,priority=false,className=''}:{product:Product;priority?:boolean;className?:string}){return product.image?<Image src={product.image} alt={product.name} width={640} height={640} className={'product-image '+className} priority={priority} unoptimized={product.image.endsWith('.svg')}/>:<div className="image-placeholder"><ShoppingBag size={50}/><span>{product.name}</span></div>}
export function ProductCard({product}:{product:Product}){const {data,add,wishlist,favorite}=useStore();const brand=data.brands.find((b:any)=>b.id===product.brand_id);const discount=product.sale_price!=null&&product.sale_price<product.price?Math.round((1-product.sale_price/product.price)*100):0;const available=product.type==='Simple'&&product.stock-(product.reserved||0)>0;
 return <article className="product-card"><div className="product-card-image"><Link href={'/products/'+product.slug}><ProductImage product={product}/></Link>{discount>0&&<span className="offer-badge">Save {discount}%</span>}<button className={'favorite-button '+(wishlist.includes(product.id)?'selected':'')} aria-label={(wishlist.includes(product.id)?'Remove from':'Add to')+' wishlist: '+product.name} onClick={()=>favorite(product.id)}><Heart size={18} fill={wishlist.includes(product.id)?'currentColor':'none'}/></button></div><div className="product-card-info"><small className="product-brand">{brand?.name||'OLIVE COLLECTION'}</small><Link href={'/products/'+product.slug}><h3>{product.name}</h3></Link><div className="product-price"><strong>{money(price(product))}</strong>{discount>0&&<del>{money(product.price)}</del>}</div><div className="product-card-bottom"><span className={available?'in-stock':'out-stock'}><i/>{available?'In stock':'Out of stock'}</span><button className="add-button" disabled={!available} aria-label={'Add '+product.name+' to bag'} onClick={()=>add(product)}><Plus size={16}/>Add</button></div></div></article>;
}
export function Newsletter(){const [busy,setBusy]=useState(false),[message,setMessage]=useState('');return <section className="newsletter container"><div><span className="eyebrow">A LITTLE INSPIRATION, IN YOUR INBOX</span><h2>Make yourself at home.</h2><p>New arrivals, thoughtful finds and offers worth opening.</p></div><form onSubmit={async event=>{event.preventDefault();if(busy)return;setBusy(true);setMessage('');const form=event.currentTarget;try{const result=await storeRequest('newsletter','POST',{email:new FormData(form).get('email')});setMessage(result.message);form.reset();}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}><div><input name="email" type="email" required maxLength={180} aria-label="Newsletter email" placeholder="Your email address"/><button disabled={busy} aria-label="Subscribe">{busy?'...':<ArrowRight size={21}/>}</button></div><small role="status">{message||'By subscribing, you agree to receive our newsletters. You can ask us to unsubscribe at any time.'}</small></form></section>}
export function Footer(){const {data}=useStore();const settings=data.settings;const whatsapp=(settings.whatsapp||settings.phone||'').replace(/[^0-9]/g,'');return <><Newsletter/><footer className="store-footer"><div className="container footer-grid"><div><Link href="/" className="footer-logo"><Leaf size={26}/>olive</Link><p>Good brands. Thoughtful choices.<br/>A little better, every day.</p><span className="footer-location">Kenya / KES</span></div><div><h3>Explore</h3><Link href="/products">All products</Link>{data.brands.map((b:any)=><Link key={b.id} href={'/brands/'+slugify(b.name)}>{b.name}</Link>)}<Link href="/products?sale=1">Special offers</Link></div><div><h3>Here to help</h3>{[['About us','about'],['Contact us','contact'],['Frequently asked questions','faq'],['Shipping & returns','shipping-returns'],['My account','account']].map(([label,path])=><Link key={path} href={'/'+path}>{label}</Link>)}</div><div><h3>Get in touch</h3>{settings.phone&&<a href={'tel:'+settings.phone}>{settings.phone}</a>}{settings.email&&<a href={'mailto:'+settings.email}>{settings.email}</a>}<p>{settings.address||'Kenya'}</p>{whatsapp&&<a href={'https://wa.me/'+whatsapp} target="_blank" rel="noreferrer">Chat on WhatsApp <ArrowRight size={13}/></a>}</div></div><div className="container footer-bottom"><span>Copyright {new Date().getFullYear()} {settings.store_name||'Olive'}. All rights reserved.</span><div><Link href="/privacy">Privacy policy</Link><Link href="/terms-conditions">Terms & conditions</Link></div><span>Built around everyday living.</span></div></footer>{whatsapp&&<a className="whatsapp-float" href={'https://wa.me/'+whatsapp} aria-label="Chat on WhatsApp" target="_blank" rel="noreferrer"><MessageCircle size={24}/></a>}</>}
export function Benefits(){return <section className="benefits container">{[[Truck,'Delivery, made simple','Rates tailored to your county'],[ShieldCheck,'Brands you know','Products from trusted names'],[Headphones,'A helping hand','Real people, ready to help']].map(([Icon,title,text]:any)=><div key={title}><Icon size={27} strokeWidth={1.4}/><span><strong>{title}</strong><small>{text}</small></span></div>)}</section>}
''')
(r/'app/layout.tsx').write_text('''import type {Metadata} from 'next';
import {catalog} from '@/lib/store';
import {StoreProvider,Header,Footer} from '@/components/store';
import './globals.css';
export const dynamic='force-dynamic';
export const metadata:Metadata={metadataBase:new URL(process.env.NEXT_PUBLIC_SITE_URL||'http://127.0.0.1:3000'),title:{default:'Olive | A better everyday',template:'%s | Olive'},description:'Shop home appliances from Karcher, Midea and LG. Thoughtful choices, delivered across selected Kenyan counties.'};
export default async function Layout({children}:{children:React.ReactNode}){const data=await catalog();return <html lang="en"><body><StoreProvider data={data}><a className="skip-link" href="#main">Skip to content</a><Header/>{children}<Footer/></StoreProvider></body></html>}
''')
(r/'app/page.tsx').write_text('''import Link from 'next/link';
import {ArrowUpRight,ArrowRight,Leaf} from 'lucide-react';
import {catalog,slugify} from '@/lib/store';
import {ProductCard,ProductImage,Benefits} from '@/components/store';
export default async function Home(){const data=await catalog();const hero=data.banners.find(b=>b.placement==='Hero slider');const categories=data.categories.filter(c=>c.parent_id&&data.products.some(p=>p.category_ids?.includes(c.id))).slice(0,5);const heroProducts=[...data.products].filter(p=>p.image).sort((a,b)=>Number(a.name.toLowerCase().includes('washer'))-Number(b.name.toLowerCase().includes('washer'))).slice(-2);return <main id="main"><section className="hero container"><div className="hero-copy"><span className="eyebrow"><span className="tiny-dot"/>GOOD THINGS START AT HOME</span><h1>Everyday living.<br/>Thoughtfully<br/><em>upgraded.</em></h1><p>{hero?.description||'Discover appliances that do more, so you can enjoy the little things. Beautifully practical. Reliably yours.'}</p><div className="hero-actions"><Link className="button" href="/products">Explore the collection <ArrowRight size={17}/></Link><span>Find your everyday upgrade</span></div><div className="hero-brand-note"><span>YOUR FAVORITE BRANDS, ALL HERE</span><div>{data.brands.map(b=><Link href={'/brands/'+slugify(b.name)} key={b.id} className={'brand-word '+slugify(b.name)}>{b.name}</Link>)}</div></div></div><div className="hero-visual"><div className="hero-circle"/><span className="hero-visual-caption">LESS EFFORT.<br/>MORE LIVING.</span>{heroProducts.map((p,i)=><Link href={'/products/'+p.slug} key={p.id} className={'hero-appliance hero-appliance-'+i}><ProductImage product={p} priority/></Link>)}<div className="hero-note"><Leaf size={21}/><span>A better everyday<br/><strong>starts right here.</strong></span></div><span className="hero-index">01 / THE HOME EDIT</span></div></section><Benefits/><section className="container section"><div className="section-heading"><div><span className="eyebrow">ROOM FOR SOMETHING BETTER</span><h2>Made for the way you live.</h2></div><Link href="/products">Explore all categories <ArrowUpRight size={17}/></Link></div><div className="category-grid">{categories.map((c,index)=>{const p=data.products.find(p=>p.category_ids?.includes(c.id));return <Link className={'category-card category-'+index} href={'/categories/'+c.slug} key={c.id}><span>{c.name}</span>{p&&<ProductImage product={p}/>}<small>Explore collection <ArrowUpRight size={15}/></small></Link>})}</div></section><section className="container section"><div className="section-heading"><div><span className="eyebrow">A FEW EVERYDAY FAVORITES</span><h2>Good choices. Great brands.</h2></div><Link href="/products">Shop all products <ArrowUpRight size={17}/></Link></div><div className="product-grid">{data.products.slice(0,4).map(p=><ProductCard key={p.id} product={p}/>)}</div></section><section className="container editorial"><div><span className="eyebrow">A FRESH PERSPECTIVE</span><h2>Less time on chores.<br/><em>More time for you.</em></h2><p>Meet the hardworking helpers that make a clean home feel effortless.</p><Link className="button" href={'/brands/'+slugify(data.brands.find(b=>b.name.includes('rcher'))?.name||'Karcher')}>Discover cleaning essentials <ArrowRight size={17}/></Link></div><div className="editorial-image">{data.products.find(p=>p.name.toLowerCase().includes('cleaner'))&&<ProductImage product={data.products.find(p=>p.name.toLowerCase().includes('cleaner'))!}/>}<span>CLEANER SPACES.<br/>CLEARER MINDS.</span></div></section><section className="container section"><div className="section-heading"><div><span className="eyebrow">YOUR NEXT GREAT FIND</span><h2>Fresh additions to your home.</h2></div><Link href="/products?sort=newest">See what's new <ArrowUpRight size={17}/></Link></div><div className="product-grid">{[...data.products].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,4).map(p=><ProductCard key={p.id} product={p}/>)}</div></section></main>}
''')
